cd /tmp && mkdir -p binlog-reader && cd binlog-reader && cat > Program.cs << 'EOF'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD ERRORS ===");
build.VisitAllChildren<Error>(error => {
    Console.WriteLine($"[ERROR] Project: {GetProjectName(error)} | Code: {error.Code} | File: {error.File}({error.LineNumber},{error.ColumnNumber})");
    Console.WriteLine($"        Message: {error.Message}");
    Console.WriteLine();
});

Console.WriteLine("=== BUILD WARNINGS ===");
build.VisitAllChildren<Warning>(warning => {
    if (warning.Code?.StartsWith("CS") == true || warning.Code?.StartsWith("NU") == true)
    {
        Console.WriteLine($"[WARN] Project: {GetProjectName(warning)} | Code: {warning.Code} | {warning.Message}");
    }
});

static string GetProjectName(BaseNode node) {
    var current = node.Parent;
    while (current != null) {
        if (current is Project p) return p.Name;
        current = current.Parent;
    }
    return "unknown";
}
EOF
