using System;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine($"Build succeeded: {build.Succeeded}");
Console.WriteLine();

Console.WriteLine("=== ALL ERRORS ===");
build.VisitAllChildren<Error>(error => {
    Console.WriteLine($"[ERROR] Project: {GetProjectName(error)} | Code: {error.Code}");
    Console.WriteLine($"        File: {error.File}({error.LineNumber},{error.ColumnNumber})");
    Console.WriteLine($"        Text: {error.Text}");
    Console.WriteLine();
});

Console.WriteLine("=== CHECKING FOR CASCADING FAILURES ===");
build.VisitAllChildren<Build>(b => {
    // nothing
});

static string GetProjectName(BaseNode node) {
    var current = node.Parent;
    while (current != null) {
        if (current is Project p) return p.Name;
        current = current.Parent;
    }
    return "unknown";
}
EOF
